 static List<String> run(ClassLoader l)throws Exception{List<String>o=new ArrayList<String>();for(String cn:new String[]{"com.sunwayworld.framework.converter.string.StringToBooleanConverter","com.sunwayworld.framework.converter.bool.BooleanToStringConverter","com.sunwayworld.framework.converter.reader.ReaderToStringConverter","com.sunwayworld.framework.converter.string.StringToPropertiesConverter"}){Class<?> c=l.loadClass(cn);Object inst=c.getField("INSTANCE").get(null);for(Object v:new Object[]{null,"true","no","line=one\nsecond=two",new StringReader("a\nb")})try{o.add(cn+":"+(v==null?"null":v instanceof Reader?"reader":v)+"="+c.getMethod("convert",(Class<?>)c.getMethod("getSourceType").invoke(inst)).invoke(inst,v));}catch(InvocationTargetException e){o.add(cn+":"+(v==null?"null":v instanceof Reader?"reader":v)+"=!"+e.getCause().getClass().getName());}catch(IllegalArgumentException e){o.add(cn+":"+(v==null?"null":v instanceof Reader?"reader":v)+"=skip");}}Class<?> id=l.loadClass("com.sunwayworld.framework.converter.IdentityConverter");Object i=id.newInstance();o.add("identity="+id.getMethod("convert",Object.class).invoke(i,"x"));return o;}
